// RBAC（含 own 资源级 ABAC-lite）：纯函数判定器，多组正反用例
const ROLE_PERMISSIONS = {
  admin: ['*'],
  editor: ['article:read', 'article:write', 'article:delete:own'],
  author: ['article:read', 'article:write:own', 'article:delete:own'],
  viewer: ['article:read'],
};

function hasPermission(role, permission) {
  const perms = ROLE_PERMISSIONS[role] || [];
  return perms.indexOf('*') >= 0 || perms.indexOf(permission) >= 0;
}

// 判定：先看角色级权限，再看"仅限本人资源"的 own 后缀
function can(actor, action, resource) {
  if (hasPermission(actor.role, action)) return true;
  if (hasPermission(actor.role, action + ':own') && resource && resource.ownerId === actor.id) return true;
  return false;
}

const alice = { id: 'u1', role: 'editor' };
const bob = { id: 'u2', role: 'author' };
const carol = { id: 'u3', role: 'viewer' };
const mansArticle = { id: 'a1', ownerId: 'u9' };
const bobsArticle = { id: 'a2', ownerId: 'u2' };

const cases = [
  ['admin_delete_any', { id: 'u0', role: 'admin' }, 'article:delete', mansArticle, true],
  ['editor_write_others', alice, 'article:write', mansArticle, true],
  ['editor_delete_others', alice, 'article:delete', mansArticle, false],
  ['editor_delete_own', alice, 'article:delete', { id: 'a3', ownerId: 'u1' }, true],
  ['author_write_own', bob, 'article:write', bobsArticle, true],
  ['author_write_others', bob, 'article:write', mansArticle, false],
  ['viewer_read', carol, 'article:read', mansArticle, true],
  ['viewer_write', carol, 'article:write', mansArticle, false],
  ['unknown_role', { id: 'u4', role: 'ghost' }, 'article:read', mansArticle, false],
];
let pass = 0;
for (const [name, actor, action, res, expect] of cases) {
  const got = can(actor, action, res);
  if (got === expect) pass += 1;
  console.log(name + ' expect=' + expect + ' got=' + got + ' match=' + (got === expect));
}
console.log('pass_count=' + pass + '/' + cases.length);
console.log('all_match=' + (pass === cases.length));
